    },
    {
      "id": "US3",
      "description": "Jako użytkownik chcę przed potwierdzeniem rezerwacji widzieć zasady anulowania i ograniczenia czasowe aby świadomie podjąć decyzję."
    },
    {
      "id": "US4",
      "description": "Jako użytkownik chcę anulować własną rezerwację zgodnie z obowiązującą polityką aby móc reagować na zmianę planów."
    },
    {
      "id": "US5",
      "description": 'Jako użytkownik chcę otrzymać jasną informację, gdy anulowanie nie jest już dozwolone lub wymaga dodatkowej zgody aby rozumieć dalsze możliwe kroki.'
    },
    {
      'id': 'US6',
      'description': 'Jako użytkownik chcę otrzymywać powiadomienia o utworzeniu, anulowaniu lub zmianie mojej wizyty aby mieć aktualną informację o statusie rezerwacji.'
    },
    {
      'id': 'US7',
      'description': 'Jako użytkownik chcę widzieć czytelne statusy terminów i rezerwacji aby rozumieć czy termin jest dostępny, zajęty, warunkowo dostępny, zmieniony czy anulowany.'
    },
    {
      'id': 'US8',
      'description': 'Jako specjalista chcę zarządzać własnym grafikiem poprzez dodawanie, edycję i usuwanie slotów aby kontrolować swoją dostępność.'
    },
    {
      'id': 'US9',
      'description': 'Jako specjalista chcę widzieć wpływ zmian grafiku na istniejące rezerwacje aby podejmować świadome decyzje przed zapisaniem zmian.'
    },
    {
      'id': 'US10',
      'description': 'Jako specjalista chcę inicjować zmiany dotyczące istniejących rezerwacji zgodnie z polityką systemu aby dostosować grafik do sytuacji wyjątkowych.'
    },
    {
      'id': 'US11',
      'description': 'Jako administrator chcę konfigurować polityki anulacji, wyjątków od konfliktów i zasad zmian grafiku aby dopasować system do różnych usług, specjalistów lub partnerów.'
    },
    {
      'id': 'US12',
      'description': 'Jako administrator chcę wykonywać nadzorowane wyjątki od reguł konfliktów z obowiązkowym uzasadnieniem aby obsługiwać uzasadnione przypadki niestandardowe.'
    },
    {
        'id': 'US13',
        'description': 'Jako administrator chcę przeglądać audyt działań krytycznych aby analizować incydenty, reklamacje i zgodność operacyjną.'
     },
     {
        'id': 'US14',
        'description': 'Jako administrator chcę zarządzać rolami i uprawnieniami aby zapewnić właściwy dostęp do danych i operacji dla każdej grupy użytkowników.'
     },
     {
        'id': 'US15',
        'description': 'Jako użytkownik chcę otrzymać zrozumiały komunikat gdy wybrany termin stał się niedostępny podczas rezerwacji aby móc szybko wybrać alternatywę.'
     },
     {
        'id': 'US16',
        'description': 'Jako specjalista chcę mieć dostęp do historii zmian własnego grafiku i powiązanych decyzji aby móc wyjaśniać przyczyny modyfikacji.'
     },
     {
        'id': 'US17',
        'description': 'Jako administrator biznesowy chcę przeglądać raporty KPI dotyczące obłożenia, anulacji, skuteczności realizacji wizyt i użycia wyjątków aby optymalizować polityki operacyjne.'
     },
     {
        'id': 'US18',
        'description': 'Jako użytkownik korzystający z urządzenia mobilnego lub technologii asystujących chcę móc wygodnie wykonać przeglądanie terminów, rezerwację i anulowanie aby system był dla mnie realnie dostępny.'
     }
  ]
}

