User stories:
[{"id": "US1", "description": "Jako Pacjent chcę przeglądać kalendarz dostępnych terminów u wybranego specjalisty z wizualnym rozróżnieniem statusów (dostępny, zajęty, zablokowany), aby szybko znaleźć odpowiedni termin wizyty."}, {"id": "US2", "description": "Jako Pacjent chcę zarezerwować wybrany termin wizyty w maksymalnie 3 krokach z natychmiastowym potwierdzeniem, aby mieć pewność że termin jest zarezerwowany wyłącznie dla mnie."}, {"id": "US3", "description": "Jako Pacjent chcę zobaczyć czytelne zasady anulowania wizyty (okna czasowe, ewentualne opłaty) przed finalizacją rezerwacji i potwierdzić ich akceptację, aby świadomie podjąć decyzję o rezerwacji."}, {"id": "US4", "description": "Jako Pacjent chcę anulować rezerwację wizyty z poziomu mojego panelu, aby móc zarządzać swoim harmonogramem, przy czym system poinformuje mnie o ewentualnych opłatach wynikających z polityki anulowania."}, {"id": "US5", "description": "Jako Pacjent chcę otrzymywać powiadomienia e-mail lub push o potwierdzeniu rezerwacji, zmianie terminu przez specjalistę oraz przypomnienie przed wizytą, aby być na bieżąco informowany o statusie moich wizyt."}, {"id": "US6", "description": "Jako Pacjent chcę mieć możliwość eksportu i usunięcia moich danych osobowych z systemu, aby korzystać z przysługującego mi prawa do bycia zapomnianym zgodnie z RODO."}, {"id": "US7", "description": "Jako Specjalista chcę zarządzać własnym grafikiem poprzez dodawanie, modyfikowanie i blokowanie terminów w intuicyjnym panelu z możliwością masowej edycji, aby efektywnie planować swoją pracę."}, {"id": "US8", "description": "Jako Specjalista chcę być automatycznie powiadamiany o nowych rezerwacjach i anulowaniach wizyt przez pacjentów, aby na bieżąco śledzić swój harmonogram."}, {"id": "US9", "description": "Jako Specjalista chcę móc zmodyfikować termin dla którego istnieje aktywna rezerwacja, przy czym system automatycznie powiadomi pacjenta i zaproponuje alternatywny termin, aby zmiany w moim grafiku były obsługiwane w sposób transparentny."}, {"id": "US10", "description": "Jako Specjalista chcę zsynchronizować mój grafik z zewnętrznym kalendarzem (Google Calendar, iCal), aby uniknąć konfliktów między rezerwacjami w systemie a innymi zobowiązaniami."}, {"id": "US11", "description": "Jako Administrator chcę konfigurować politykę anulowania wizyt (okna czasowe, opłaty, wyjątki) dla poszczególnych specjalistów lub specjalizacji, aby elastycznie zarządzać zasadami platformy."}, {"id": "US12", "description": "Jako Administrator chcę zatwierdzać wyjątki od reguł konfliktów rezerwacji z obowiązkowym uzasadnieniem rejestrowanym w logu audytowym, aby mieć pełną kontrolę i rozliczalność nad niestandardowymi przypadkami."}, {"id": "US13", "description": "Jako Administrator chcę przeglądać panel analityczny z metrykami biznesowymi (wykorzystanie terminów, przychód na specjalistę, wskaźnik no-show, retencja użytkowników), aby podejmować decyzje oparte na danych."}, {"id": "US14", "description": "Jako Administrator chcę przeglądać pełny, niemodyfikowalny log audytowy wszystkich operacji w systemie z możliwością filtrowania po użytkowniku, typie operacji i przedziale czasowym, aby zapewnić rozliczalność i wykrywać nadużycia."}, {"id": "US15", "description": "Jako Administrator chcę zarządzać kontami użytkowników i specjalistów oraz przypisywać role i uprawnienia zgodnie z zasadą najmniejszych uprawnień, aby zapewnić bezpieczeństwo i właściwą separację dostępu."}, {"id": "US16", "description": "Jako Pacjent chcę zalogować się do systemu z użyciem wieloskładnikowego uwierzytelniania (MFA), aby moje konto i dane medyczne były odpowiednio chronione przed nieautoryzowanym dostępem."}, {"id": "US17", "description": "Jako Pacjent chcę przy próbie rezerwacji zajętego terminu otrzymać czytelny komunikat błędu wraz z sugestią najbliższych dostępnych alternatywnych terminów u tego samego specjalisty, aby szybko znaleźć odpowiedni termin."}, {"id": "US18", "description": "Jako Specjalista chcę przeglądać podstawowe informacje o pacjentach posiadających aktywne rezerwacje w moim grafiku, aby odpowiednio przygotować się do wizyt, bez dostępu do danych innych użytkowników systemu."}, {"id": "US19", "description": "Jako nowy użytkownik chcę przejść przez onboarding wyjaśniający kluczowe funkcje systemu po pierwszym zalogowaniu, aby szybko nauczyć się korzystać z platformy bez potrzeby zewnętrznej pomocy."}, {"id": "US20", "description": "Jako Administrator chcę konfigurować ustawienia lokalne platformy (język, waluta, strefa czasowa, lokalne przepisy) dla nowych rynków geograficznych bez zmian w kodzie systemu, aby sprawnie skalować platformę na nowe regiony."}]

